<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(empty($_SESSION['reseller_id'])){header('Location: reseller-login.php');exit;}$rid=(int)$_SESSION['reseller_id'];$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$codes=preg_split('/[\s,;]+/',strtoupper(trim($_POST['codes']??'')),-1,PREG_SPLIT_NO_EMPTY);$codes=array_values(array_unique($codes));if(!$codes||count($codes)>500)$error='Informe entre 1 e 500 códigos de placas.';else{$pdo=db();$pdo->beginTransaction();try{$find=$pdo->prepare("SELECT id FROM plaques WHERE code=? AND status='stock' AND reseller_id IS NULL FOR UPDATE");$assign=$pdo->prepare('UPDATE plaques SET reseller_id=?,sold_at=NULL WHERE id=? AND status=\'stock\' AND reseller_id IS NULL');$done=[];foreach($codes as $code){if(!preg_match('/^ED[0-9]{8}$/',$code))throw new RuntimeException('Código inválido: '.$code);$find->execute([$code]);$p=$find->fetch();if(!$p)throw new RuntimeException('Placa '.$code.' não existe, já foi ativada ou pertence a outro revendedor.');$assign->execute([$rid,$p['id']]);if($assign->rowCount()!==1)throw new RuntimeException('Não foi possível registrar '.$code);$done[]=$code;}$pdo->commit();$success=count($done).' placa(s) adicionada(s) ao seu estoque.';}catch(Throwable $e){$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Erro ao registrar as placas.';}}}
$q=db()->prepare("SELECT code,created_at FROM plaques WHERE reseller_id=? AND status='stock' ORDER BY id DESC");$q->execute([$rid]);$rows=$q->fetchAll();
layout_start('Painel do revendedor');
?><div class="heading"><div><span class="eyebrow">PORTAL DO REVENDEDOR</span><h1>Olá, <?=e($_SESSION['reseller_name']??'Revendedor')?></h1><p>Cadastre os códigos das placas que você comprou nos marketplaces.</p></div><a class="button secondary" href="reseller-logout.php">Sair</a></div><?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice"><?=e($success)?></div><?php endif;?><form method="post" class="panel"><?=client_csrf_field()?><h2>Adicionar placas ao meu estoque</h2><p>Digite os códigos impressos nas placas. Separe por linha, espaço ou vírgula. A chave de ativação do comprador não será consumida.</p><label>Códigos das placas<textarea name="codes" rows="6" placeholder="ED00000001&#10;ED00000002" required></textarea></label><button>Registrar placas</button></form><section class="panel"><h2>Meu estoque (<?=count($rows)?>)</h2><div class="tablewrap"><table><thead><tr><th>Placa</th><th>Link QR/NFC</th><th>Estado</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['code'])?></b></td><td><a href="<?=e(app_url('r/'.$r['code']))?>" target="_blank"><?=e(app_url('r/'.$r['code']))?></a></td><td>Disponível</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="3">Nenhuma placa registrada ainda.</td></tr><?php endif;?></tbody></table></div></section><?php layout_end();?>